import { CartResponseV2, CartResponseV2CartItem, PaymentResponse } from "@parksandresorts/webapiproxy-types";
import {
  AddToCartGTMEvent,
  BeginCheckoutGTMEvent,
  GTMEvent,
  PurchaseGTMEvent,
  ResetEcommerceGTMEvent,
} from "../types/tracking/google-tag-manager";
import { EventAggregator, isNonEmptyArray, redeemableDataForCartItem } from ".";

// NOTE!
// The price in the ecommerce object is expected to be excluding VAT according to the Google documentation, but TAS (our
// marketing partner) says that we should include VAT in the price. It seems like this is common in Sweden.

const cartItemsToEcommerceItems = (
  cartItems: Array<CartResponseV2CartItem>,
  discountItems: CartResponseV2["discountItems"],
  redeemableValidationResults: CartResponseV2["redeemableValidationResults"],
) => {
  return cartItems.map((item) => {
    const redeemableData = redeemableDataForCartItem(item, discountItems, redeemableValidationResults);
    const commaSeperatedVouchers = redeemableData
      .filter((data) => data.type === "voucher")
      .map((data) => data.code)
      .join(",");

    const totalDiscount = isNonEmptyArray(redeemableData)
      ? redeemableData.reduce((sum, data) => sum + (Math.abs(data.amount) || 0), 0)
      : undefined;

    const hasMoreQuantityThanOne = item.quantity > 1;

    const commonFields = {
      item_id: `${item.productId}`,
      item_name: item.productName,
      coupon: commaSeperatedVouchers || undefined,
    };

    if (!hasMoreQuantityThanOne) {
      return {
        ...commonFields,
        price: item.price.amount.amountIncludingVat, // NOTE: This is including VAT, See the note at the top of this file.
        quantity: 1,
        discount: totalDiscount,
      };
    }

    //The documentation says that "If a discount applies to the item, set price to the discounted unit price".
    //The field we have is unitPriceIncludingVat but that is _before_ eventual discounts.
    //So instead we use amountIncludingVat (which is the total price for all the quantities after discount), and divide that by quantity to get the discounted unit price.
    return {
      ...commonFields,
      price: item.price.amount.amountIncludingVat / item.quantity, // NOTE: This is including VAT, See the note at the top of this file.
      quantity: item.quantity,
      discount: totalDiscount ? totalDiscount / item.quantity : undefined, //We don't know how the discount is distributed among the items, so we just assume it's evenly distributed.
    };
  });
};

export const cartItemsToAddToCartGTMEvent = (
  cartItems: Array<CartResponseV2CartItem>,
  discountItems: CartResponseV2["discountItems"],
  redeemableValidationResults: CartResponseV2["redeemableValidationResults"],
): AddToCartGTMEvent => {
  const items = cartItemsToEcommerceItems(cartItems, discountItems, redeemableValidationResults);
  return {
    event: "add_to_cart",
    ecommerce: {
      currency: "SEK",
      value: items.reduce((sum, item) => sum + item.price * item.quantity, 0),
      items,
    },
  };
};

export const cartToBeginCheckoutGTMEvent = (cart: CartResponseV2): BeginCheckoutGTMEvent => {
  return {
    event: "begin_checkout",
    ecommerce: {
      currency: "SEK",
      value: cart.cartPrice.amount.amountIncludingVat, // NOTE: This is including VAT, which is not what Google's documentation says we should use. See the note at the top of this file.
      items: cartItemsToEcommerceItems(cart.cartItems, cart.discountItems, cart.redeemableValidationResults),
    },
  };
};

export const paymentToPurchaseGTMEvent = (cart: CartResponseV2, payment: PaymentResponse): PurchaseGTMEvent => {
  return {
    event: "purchase",
    ecommerce: {
      currency: "SEK",
      value: payment.cartTotalAmount, // NOTE: This is including VAT, which is not what Google's documentation says we should use. See the note at the top of this file.
      transaction_id: payment.cartGuid,
      // TODO: implement shipping prop
      // shipping: 0,
      tax: payment.cartTotalVat,
      items: cartItemsToEcommerceItems(cart.cartItems, cart.discountItems, cart.redeemableValidationResults),
    },
  };
};

/**
 * trackEcommerceEvent is a tiny helper built around EventAggregator so that we don't forget to reset the ecommerce object before pushing a new event.
 *
 * It is not apparent to me why we need to reset the ecommerce object before pushing a new event, but it is in the documentation, so we better do it.
 * https://developers.google.com/analytics/devguides/collection/ga4/reference/events?client_type=gtm
 */
export const trackEcommerceEvent = (event: Exclude<GTMEvent, ResetEcommerceGTMEvent>) => {
  EventAggregator.publish("gtmEvent", { ecommerce: null });
  EventAggregator.publish("gtmEvent", event);
};
