import { useEffect, useRef } from "react";

/**
 * A hook similar to useEffect, but provides the previous values of the dependencies to the effect function.
 *
 * @param effect The effect to trigger on changes to the dependencies. Can return a destructor function, just like in useEffect.
 * @param deps An array of dependencies. Use `as const` to ensure the types are inferred properly by TS in the effect function.
 * @returns
 */
export const useEffectWithPrevious = <T extends React.DependencyList>(
  effect: (prevDeps: T, initialTrigger: boolean) => void | (() => void),
  deps: T,
) => {
  const prevDeps = useRef<T | undefined>(deps);
  useEffect(() => {
    const destructor = effect(prevDeps.current ?? deps, prevDeps.current === undefined);
    prevDeps.current = deps;
    return destructor;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
};
