import { PropsWithChildren, createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
import { DateHelper, EventAggregator, LocalStorageHelper, LocationHelper, TodayHelper, throwError } from "../helpers";
import {
  CartRequestCartItem,
  CartResponseV2,
  CartResponseV2CartItem,
  CartState,
} from "@parksandresorts/webapiproxy-types";
import {
  useAddMultipleItemsToCartMutation,
  useAddToCartMutation,
  useApplyDealCodeToCart,
  useCart,
  usePatchCartMutation,
  useRemoveCartItemMutation,
  useUpdateCartItemQuantityMutation,
} from "../hooks/shop-service-hooks";
import dayjs from "dayjs";
import { cartItemsToAddToCartGTMEvent, trackEcommerceEvent } from "../helpers/gtm-helper";
import { Language } from "../labels/i18n";
import { useAuthState } from "../auth";
import { useEffectWithPrevious } from "../hooks/use-effect-with-previous";

const DefaultLocalStorageKey = "shop-service-cart-id";

// States in which a cart can no longer be shopped and should be forgotten. Transient checkout
// states (LockedForPayment/PaymentInitialized) are intentionally excluded so an in-progress
// payment is never dropped from under the user, and ParkPaymentFailed is excluded so the user can
// retry payment without losing the cart.
const ForgettableCartStates: ReadonlySet<CartState> = new Set([CartState.EXPIRED, CartState.PAID]);

/**
 * Whether a cart should be forgotten (its id dropped from local storage). True when the cart has
 * reached a terminal state (expired, or paid but the confirmation page was never reached), or when
 * its `expiresOn` timestamp has passed relative to `now` - the latter can happen while the backend
 * still reports `Open`, before a background job flips the state.
 */
export function shouldForgetCart(cart: CartResponseV2 | undefined, now: Date): boolean {
  if (!cart) return false;
  if (ForgettableCartStates.has(cart.state)) return true;
  return DateHelper.isBefore(cart.timestamps.expiresOn, now);
}

export type ShopServiceCartContextModifiers = {
  addCartItem: (item: CartRequestCartItem) => Promise<Array<CartResponseV2CartItem>>;
  removeCartItem: (cartItemGuid: string) => Promise<CartResponseV2CartItem>;
  /** updateCartItemQuantity might return undefined in cases where quantity is set to 0 */
  updateCartItemQuantity: (cartItemGuid: string, quantity: number) => Promise<CartResponseV2CartItem | undefined>;
  /** Adds multiple items to the existing cart, or creates a new one, and returns the newly added items */
  addMultipleCartItems: (items: Array<CartRequestCartItem>) => Promise<Array<CartResponseV2CartItem>>;
  forgetCartIfActive: (cartIdToForget: string) => void;
  emptyCart: () => Promise<void>;
};
export type ShopServiceCartContextType = Omit<ReturnType<typeof useCart>, "isLoading"> &
  ShopServiceCartContextModifiers & {
    // This is technically already included in the type returned by useCart, but we want to be able to set it as `isLoading` in
    // more cases, whereas the TanStack isLoading-value/type is very tightly coupled with other properties, such as `status`.
    isLoading: boolean;
    cartId: string | undefined;
  };
const ShopServiceCartContext = createContext<ShopServiceCartContextType>(
  // This default value is never used, since the context is always wrapped in a provider with a value.
  null as unknown as ShopServiceCartContextType,
);

function initialCartId(localStorageKey: string): string | undefined {
  const cartId = LocalStorageHelper.getItem(localStorageKey);
  return cartId;
}

export type ShopServiceCartContextProps = PropsWithChildren<{ currentLocale: Language; localStorageKey?: string }>;
export const ShopServiceCartContextProvider = ({
  children,
  currentLocale,
  localStorageKey = DefaultLocalStorageKey,
}: ShopServiceCartContextProps) => {
  const [cartId, setCartId] = useState(() => initialCartId(localStorageKey));
  const [isLoadingInitial, setIsLoadingInitial] = useState(cartId !== undefined);
  const auth = useAuthState();

  const cartResult = useCart(cartId);
  const { data: cart, isLoading: isCartLoading, error: cartError } = cartResult;

  const { mutateAsync: patchCartMutation, isPending: patchCartPending } = usePatchCartMutation(cartId, currentLocale);
  const { mutateAsync: addCartItemMutation, isPending: addCartItemPending } = useAddToCartMutation(
    cartId,
    currentLocale,
  );
  const { mutateAsync: removeCartItemMutation, isPending: removeCartItemPending } = useRemoveCartItemMutation(cartId);
  const { mutateAsync: updateCartItemQuantityMutation, isPending: updateCartItemQuantityPending } =
    useUpdateCartItemQuantityMutation(cartId);
  const { mutateAsync: addMultipleCartItemsMutation, isPending: addMultipleCartItemsPending } =
    useAddMultipleItemsToCartMutation(cartId, currentLocale);
  const { mutateAsync: applyDealCode, isPending: applyDealCodePending } = useApplyDealCodeToCart(cartId, currentLocale);

  const isLoading =
    isCartLoading ||
    isLoadingInitial ||
    patchCartPending ||
    addCartItemPending ||
    removeCartItemPending ||
    updateCartItemQuantityPending ||
    addMultipleCartItemsPending ||
    applyDealCodePending;

  const addCartItem = useCallback(
    async (item: CartRequestCartItem) => {
      const response = await addCartItemMutation({ item, myParksSessionToken: auth?.cookieString });
      if (response?.cartGuid && response.cartGuid !== cartId) {
        setCartId(response.cartGuid);
      }
      const existingCartItems = new Set(cart?.cartItems.map((item) => item.cartItemGuid));
      const addedItems = response.cartItems.filter((item) => !existingCartItems.has(item.cartItemGuid));

      trackEcommerceEvent(
        cartItemsToAddToCartGTMEvent(addedItems, response.discountItems, response.redeemableValidationResults),
      );

      return addedItems;
    },
    [addCartItemMutation, cartId, cart?.cartItems, auth?.cookieString],
  );

  const removeCartItem = useCallback(
    async (cartItemGuid: string) => {
      const itemToRemove =
        cart?.cartItems.find((item) => item.cartItemGuid === cartItemGuid) ?? throwError("Item not found in cart");
      await removeCartItemMutation(cartItemGuid);

      return itemToRemove;
    },
    [cart?.cartItems, removeCartItemMutation],
  );
  const updateCartItemQuantity = useCallback(
    async (cartItemGuid: string, quantity: number) => {
      const response = await updateCartItemQuantityMutation({ cartItemGuid, quantity });
      return response.cartItems.find((item) => item.cartItemGuid === cartItemGuid);
    },
    [updateCartItemQuantityMutation],
  );
  const addMultipleCartItems = useCallback(
    async (items: Array<CartRequestCartItem>) => {
      if (items.length === 0) return [];
      const response = await addMultipleCartItemsMutation({ items, myParksSessionToken: auth?.cookieString });
      if (response?.cartGuid && response.cartGuid !== cartId) {
        setCartId(response.cartGuid);
      }
      const existingCartItemIds = new Set(cart?.cartItems.map((item) => item.cartItemGuid));
      const addedItems = response.cartItems.filter((item) => !existingCartItemIds.has(item.cartItemGuid));

      trackEcommerceEvent(
        cartItemsToAddToCartGTMEvent(addedItems, response.discountItems, response.redeemableValidationResults),
      );

      return addedItems;
    },
    [addMultipleCartItemsMutation, cart?.cartItems, cartId, auth?.cookieString],
  );
  const forgetCartIfActive = useCallback(
    (cartIdToForget: string) => {
      if (cartId === cartIdToForget) {
        setCartId(undefined);
      }
    },
    [cartId],
  );
  const emptyCart = useCallback(async () => {
    if (!cart?.cartItems?.length) return;
    await Promise.all(cart.cartItems.map((item) => removeCartItem(item.cartItemGuid)));
    LocalStorageHelper.removeItem(localStorageKey);
  }, [cart, removeCartItem, localStorageKey]);
  const modifiers = {
    addCartItem,
    removeCartItem,
    updateCartItemQuantity,
    addMultipleCartItems,
    forgetCartIfActive,
    emptyCart,
  } satisfies ShopServiceCartContextModifiers;

  useEffect(() => {
    if (!isLoadingInitial) return;
    // Stop the initial-load spinner once the cart has either resolved or failed to load.
    if (cart || cartError) {
      setIsLoadingInitial(false);
    }
  }, [cart, isLoadingInitial, cartError]);

  // Forget the cart id if fetching it fails during the initial load - typically an old id in local
  // storage that the backend has expired or removed. We deliberately limit this to the initial load
  // so a transient error during normal shopping does not drop a still-valid cart.
  // TODO: we should probably handle errors more specifically than this.
  useEffect(() => {
    if (isLoadingInitial && cartError) {
      setCartId(undefined);
    }
  }, [isLoadingInitial, cartError]);

  // Forget the cart id once the cart can no longer be shopped (terminal state or past its expiry).
  useEffect(() => {
    if (shouldForgetCart(cart, TodayHelper.getNow())) {
      setCartId(undefined);
    }
  }, [cart]);

  // Set or remove the cart id in local storage when the cart id changes
  useEffect(() => {
    if (cartId) {
      LocalStorageHelper.setItem(localStorageKey, cartId, dayjs().add(1, "week"));
    } else {
      LocalStorageHelper.removeItem(localStorageKey);
    }
  }, [cartId, localStorageKey]);

  // Apply a deal code from the URL (`?deal=CODE`) on any page: create an empty cart if
  // needed, attach the code unless already present, then strip the param to keep the URL clean.
  const hasAppliedDealCodeRef = useRef(false);
  useEffect(() => {
    if (hasAppliedDealCodeRef.current) return;
    if (isLoadingInitial) return; // wait until we know whether a cart already exists
    if (typeof window === "undefined") return;

    const code = LocationHelper.getQueryParams().deal?.[0]?.trim().toUpperCase();
    if (!code) return;

    // Run the body at most once per mount: the effect re-fires when its deps change
    // (e.g. `cart` updates after we apply the code), and we must not apply it twice.
    hasAppliedDealCodeRef.current = true;

    const alreadyOnCart = cart?.voucherCodes.some((existing) => existing.toUpperCase() === code) ?? false;
    if (alreadyOnCart) {
      LocationHelper.removeQueryParam("deal");
      return;
    }

    applyDealCode({ voucherCode: code, myParksSessionToken: auth?.cookieString })
      .then((response) => {
        if (response.cartGuid && response.cartGuid !== cartId) {
          setCartId(response.cartGuid);
        }
        LocationHelper.removeQueryParam("deal");
      })
      .catch((error) => {
        EventAggregator.publish("trackException", {
          exception: error,
          customMessage: "Failed to apply deal code from URL",
        });
      });
  }, [isLoadingInitial, cart, applyDealCode, auth?.cookieString, cartId]);

  // Update myParksSessionToken on the cart when it changes
  useEffectWithPrevious(
    ([, prevAuth]) => {
      if (!cartId) {
        return;
      }
      // ignore first run
      if (prevAuth.isFetchingSession) {
        return;
      }
      // if login state didn't change, ignore
      if (prevAuth.isLoggedIn === auth.isLoggedIn) {
        return;
      }

      patchCartMutation({ myParksSessionToken: auth?.cookieString });
    },
    [cartId, auth, patchCartMutation] as const,
  );

  return (
    <>
      <ShopServiceCartContext.Provider
        value={{
          ...cartResult,
          ...modifiers,
          cartId,
          isLoading,
        }}
      >
        {children}
      </ShopServiceCartContext.Provider>
    </>
  );
};

export const useShopServiceCartContext = () => {
  const context = useContext(ShopServiceCartContext);

  if (!context) {
    throw new Error("useShopServiceCartContext must be used within an ShopServiceCartContextProvider");
  }

  return context;
};
